function destroyCharts(){state.charts.forEach(c=>{try{c.dispose()}catch(e){}});state.charts=[]} function chart(el,opt){if(!el||!window.echarts)return;const c=echarts.init(el);c.setOption(opt);state.charts.push(c)}
