function filteredData(){const fo=$('#foFilter').value,sc=$('#scaleFilter').value,q=$('#searchInput').value.trim().toLowerCase();return state.data.filter(x=>(fo==='all'||x.fo===fo)&&(sc==='all'||getScale(x)===sc)&&(!q||x.n.toLowerCase().includes(q)))}
function populateFilters(){const fos=[...new Set(state.data.map(x=>x.fo).filter(Boolean))].sort();$('#foFilter').innerHTML='<option value="all">Все округа</option>'+fos.map(x=>`<option>${esc(x)}</option>`).join('')}
function updateMeta(){ $('#periodText').textContent=state.meta.period||'Период из файла';$('#regionCount').textContent=state.data.length;$('#rankedCount').textContent=state.data.filter(x=>num(getRank(x))).length;$('#indicatorCount').textContent=state.indicatorMeta.length||'—'}
function setView(v){state.view=v;$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$$('.view').forEach(x=>x.classList.add('hidden'));const el=$('#'+v+'View');if(el)el.classList.remove('hidden');render()}
function render(){destroyCharts();const data=filteredData();({overview:renderOverview,map:renderMap,analytics:renderAnalytics,ranking:renderRanking,directions:renderDirections,region:renderRegion,diagnostics:renderDiagnostics}[state.view]||renderOverview)(data);setTimeout(()=>state.charts.forEach(c=>c.resize()),0)}
function renderOverview(data){const ranked=data.filter(x=>num(getRank(x))).sort((a,b)=>getRank(a)-getRank(b)),lead=ranked[0],avg=mean(data.map(getVal)),high=data.filter(x=>getScale(x)==='Высокая').length;$('#overviewDashboard').innerHTML=`<div class="section-head"><div><h2>Обзор комплексной оценки</h2><p>Сводная картина по выбранной группе ТО.</p></div></div><div class="kpi-grid"><div class="kpi-card"><div class="label">ТО в выборке</div><div class="value">${data.length}</div></div><div class="kpi-card"><div class="label">Среднее</div><div class="value">${pct(avg)}</div><div class="sub">${metricLabel()}</div></div><div class="kpi-card accent-high"><div class="label">Высокая оценка</div><div class="value">${high}</div></div><div class="kpi-card"><div class="label">Лидер</div><div class="value">${lead?rank(getRank(lead)):'—'}</div><div class="sub">${lead?esc(lead.n):'—'}</div></div><div class="kpi-card"><div class="label">Показателей</div><div class="value">${state.indicatorMeta.length}</div><div class="sub">в 12 направлениях</div></div></div><div class="grid-2"><div class="panel"><div class="panel-title"><div><h3>ТОП-10</h3><p>По текущему режиму оценки</p></div></div><div id="topChart" class="chart"></div></div><div class="panel"><div class="panel-title"><div><h3>Распределение оценок</h3></div></div><div id="scaleChart" class="chart"></div></div></div>`;const top=[...data].filter(x=>num(getVal(x))).sort((a,b)=>getVal(b)-getVal(a)).slice(0,10).reverse();if(top.length)chart($('#topChart'),{...chartBase(),xAxis:{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%'}},yAxis:{type:'category',data:top.map(x=>x.n),axisLabel:{width:160,overflow:'truncate'}},series:[{type:'bar',data:top.map(x=>+(getVal(x)*100).toFixed(1)),barMaxWidth:18}]});chart($('#scaleChart'),{tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['48%','72%'],data:['Высокая','Средняя','Низкая'].map(n=>({name:n,value:data.filter(x=>getScale(x)===n).length}))}]})}
function renderMap(data){const root=$('#mapDashboard'),sel=new Set(data.map(x=>x.n)),all=state.data.filter(x=>HEX_LAYOUT[x.n]),fit=state.mapMode==='fit',mobile=matchMedia('(max-width:700px)').matches,g=fit?{w:74,h:64,sx:56,sy:42,ox:28}:{w:84,h:74,sx:63,sy:48,ox:32},maxC=Math.max(...Object.values(HEX_LAYOUT).map(v=>v[0])),maxR=Math.max(...Object.values(HEX_LAYOUT).map(v=>v[1])),nw=maxC*g.sx+g.w+g.ox+24,nh=maxR*g.sy+g.h+24;const cells=all.map(x=>{const[c,r,l]=HEX_LAYOUT[x.n],cl=badgeClass(getScale(x)),dim=sel.has(x.n)?'':' dim';return`<button class="hex-cell ${cl}${dim}" data-region="${esc(x.n)}" style="left:${c*g.sx+(r%2?g.ox:0)}px;top:${r*g.sy}px;width:${g.w}px;height:${g.h}px" title="${esc(x.n)} · ${pct(getVal(x))}"><span class="hex-cell-label">${esc(l)}</span><span class="hex-cell-value">${pct(getVal(x))}</span><span class="hex-cell-rank">место ${rank(getRank(x))}</span></button>`}).join('');root.innerHTML=`<div class="section-head"><div><h2>Карта России сотами</h2><p>Плотная картограмма без лишних пробелов.</p></div><div class="map-controls"><div class="segmented"><button class="segment-btn ${fit?'active':''}" data-map-mode="fit">Вся Россия</button><button class="segment-btn ${!fit?'active':''}" data-map-mode="detail">Подробно</button></div><div class="legend-inline"><span class="legend-item"><i class="legend-swatch high"></i>Высокая</span><span class="legend-item"><i class="legend-swatch mid"></i>Средняя</span><span class="legend-item"><i class="legend-swatch low"></i>Низкая</span></div></div></div><div class="panel map-panel"><div class="panel-title"><div><h3>${fit?'Вся Россия':'Подробная карта'}</h3><p>Нажмите на соту — откроется карточка региона.</p></div><div class="note">В фильтре: <strong>${data.length}</strong></div></div><div class="hex-map-scroll ${fit?'fit-mode':'detail-mode'}"><div class="hex-map-stage"><div class="hex-map" style="width:${nw}px;height:${nh}px">${cells}</div></div></div>${fit&&mobile?'<div class="map-mobile-hint">Для процентов и мест используйте режим «Подробно».</div>':''}</div>`;$$('[data-map-mode]').forEach(b=>b.onclick=()=>{state.mapMode=b.dataset.mapMode;render()});$$('#mapDashboard .hex-cell').forEach(b=>b.onclick=()=>{state.region=b.dataset.region;setView('region')});if(fit)requestAnimationFrame(()=>{const scroll=$('#mapDashboard .fit-mode'),stage=$('#mapDashboard .hex-map-stage'),map=$('#mapDashboard .hex-map');if(!scroll)return;const s=Math.min(1,(scroll.clientWidth-2)/nw);map.style.transform=`scale(${s})`;map.style.transformOrigin='0 0';stage.style.width=nw*s+'px';stage.style.height=nh*s+'px'})}
function renderAnalytics(data){
  const root=$('#analyticsDashboard');
  const usable=data.filter(x=>num(x.v));
  if(!usable.length){ root.innerHTML='<div class="panel">Нет данных для аналитики</div>'; return; }
  const avgTO=mean(usable.map(x=>x.v));
  const avgPPK=mean(usable.map(x=>x.ppv));
  const avgCombined=mean(usable.map(x=>x.cv));
  const ranked=usable.filter(x=>num(x.r)&&num(x.pr));
  const improved=ranked.filter(x=>delta(x.r,x.pr)>0).length;
  const worsened=ranked.filter(x=>delta(x.r,x.pr)<0).length;
  const stable=ranked.filter(x=>delta(x.r,x.pr)===0).length;
  const avgByDir=DIRECTIONS.map((name,i)=>mean(usable.map(x=>x.d?.[i]?.[1]).filter(num)));
  const foStats=[...new Set(usable.map(x=>x.fo).filter(Boolean))].map(fo=>{
    const rows=usable.filter(x=>x.fo===fo);
    return {fo,to:mean(rows.map(x=>x.v)),ppk:mean(rows.map(x=>x.ppv)),combined:mean(rows.map(x=>x.cv)),n:rows.length};
  }).sort((a,b)=>(b.combined??0)-(a.combined??0));
  const bestFO=foStats[0], worstFO=foStats[foStats.length-1];

  const dirStats=DIRECTIONS.map((name,i)=>{
    const vals=usable.map(x=>x.d?.[i]?.[1]).filter(num);
    const below90=usable.filter(x=>num(x.d?.[i]?.[1])&&x.d[i][1]<.90).length;
    return {name,short:SHORT[i],avg:mean(vals),below90,n:vals.length};
  }).filter(x=>num(x.avg)).sort((a,b)=>a.avg-b.avg);
  const weakestDir=dirStats[0], strongestDir=dirStats[dirStats.length-1];

  const ppkImpact=usable.filter(x=>num(x.cv)&&num(x.v)).map(x=>({...x,impact:x.cv-x.v})).sort((a,b)=>b.impact-a.impact);
  const bestImpact=ppkImpact[0], worstImpact=ppkImpact[ppkImpact.length-1];

  const regionAnalytics = usable.map(x=>{
    const d = delta(x.r,x.pr);
    const weakDirs=(x.d||[]).map((z,i)=>({i,val:z?.[1],pts:z?.[2],max:z?.[3],avg:avgByDir[i]})).filter(o=>num(o.val));
    const drag = weakDirs.map(o=>({
      i:o.i,
      gap:num(o.avg)?Math.max(0,o.avg-o.val):0,
      val:o.val,
      avg:o.avg,
      pts:o.pts,
      max:o.max,
      lossPts:(num(o.max)&&num(o.avg)&&num(o.val))?Math.max(0,(o.avg-o.val)*o.max):0
    })).sort((a,b)=>b.lossPts-a.lossPts);
    const topDrag=drag.slice(0,3);
    const reservePoints=topDrag.reduce((s,o)=>s+o.lossPts,0);
    const potentialScore = num(x.s)&&num(x.m) ? Math.min(1,(x.s + reservePoints)/x.m) : x.v;
    const estimatedRank = 1 + usable.filter(y=>num(y.v) && y.v > potentialScore).length;
    const reserveRise = num(x.r) ? Math.max(0, x.r - estimatedRank) : null;
    let riskScore = (1-(x.v||0))*100;
    if(num(d) && d<0) riskScore += Math.abs(d)*0.8;
    riskScore += drag.filter(o=>o.val<0.9).length*1.5;
    if(num(x.ppv) && num(x.v) && x.ppv < x.v) riskScore += (x.v-x.ppv)*25;
    return {...x,d,drag,topDrag,potentialScore,estimatedRank,reserveRise,riskScore,weakDirsCount:drag.filter(o=>o.val<0.9).length};
  });

  const attention=[...regionAnalytics].sort((a,b)=>b.riskScore-a.riskScore).slice(0,12);
  const redZone=[...regionAnalytics].filter(x=>(x.v<avgTO && (x.d??0)<=0) || x.weakDirsCount>=3).sort((a,b)=>b.riskScore-a.riskScore).slice(0,10);
  const reserves=[...regionAnalytics].sort((a,b)=>(b.reserveRise||0)-(a.reserveRise||0) || (b.potentialScore-a.potentialScore)).slice(0,10);
  const heatRows=[...usable].sort((a,b)=>(a.r??999)-(b.r??999));

  const quadrant = {
    hiUp: regionAnalytics.filter(x=>x.v>=avgTO && num(x.d) && x.d>0).length,
    hiDown: regionAnalytics.filter(x=>x.v>=avgTO && (!num(x.d) || x.d<=0)).length,
    loUp: regionAnalytics.filter(x=>x.v<avgTO && num(x.d) && x.d>0).length,
    loDown: regionAnalytics.filter(x=>x.v<avgTO && (!num(x.d) || x.d<=0)).length,
  };

  root.innerHTML=`
    <div class="section-head"><div><h2>Управленческая аналитика</h2><p>Автоматические выводы для руководителя: где риски, что тянет результат вниз и где находится резерв роста.</p></div><div class="note">Фильтры сверху применяются ко всей аналитике. Резерв роста и новая позиция носят оценочный характер и рассчитываются по трём самым слабым направлениям региона относительно среднего по РФ.</div></div>
    <div class="kpi-grid">
      <div class="kpi-card"><div class="label">Средняя оценка ТО</div><div class="value">${pct(avgTO)}</div><div class="sub">по текущей выборке</div></div>
      <div class="kpi-card"><div class="label">С учетом ППК</div><div class="value">${pct(avgCombined)}</div><div class="sub">ППК отдельно: ${pct(avgPPK)}</div></div>
      <div class="kpi-card accent-high"><div class="label">Улучшили место</div><div class="value">${improved}</div><div class="sub">из ${ranked.length} сопоставимых ТО</div></div>
      <div class="kpi-card accent-low"><div class="label">Снизили место</div><div class="value">${worsened}</div><div class="sub">без изменений: ${stable}</div></div>
      <div class="kpi-card"><div class="label">Красная зона</div><div class="value">${redZone.length}</div><div class="sub">ТО с низким результатом и признаками риска</div></div>
    </div>

    <div class="grid-2 equal">
      <div class="panel"><div class="panel-title"><div><h3>Ключевые выводы</h3><p>Автоматически сформировано по текущей выборке</p></div></div>
        <div class="insight-list">
          <div class="insight-item positive"><strong>Лучший федеральный округ:</strong> ${bestFO?esc(bestFO.fo):'—'} — ${bestFO?pct(bestFO.combined):'—'} по комплексной оценке.</div>
          <div class="insight-item warning"><strong>Округ с минимальным средним:</strong> ${worstFO?esc(worstFO.fo):'—'} — ${worstFO?pct(worstFO.combined):'—'}.</div>
          <div class="insight-item negative"><strong>Самое слабое направление:</strong> ${weakestDir?esc(weakestDir.name):'—'} — среднее ${weakestDir?pct(weakestDir.avg):'—'}, ниже 90% у ${weakestDir?weakestDir.below90:0} ТО.</div>
          <div class="insight-item positive"><strong>Самое сильное направление:</strong> ${strongestDir?esc(strongestDir.name):'—'} — среднее ${strongestDir?pct(strongestDir.avg):'—'}.</div>
          <div class="insight-item"><strong>Максимальное влияние ППК вверх:</strong> ${bestImpact?esc(bestImpact.n):'—'} — ${(bestImpact&&num(bestImpact.impact)?(bestImpact.impact*100).toFixed(1).replace('.',','):'—')} п.п.; <strong>вниз:</strong> ${worstImpact?esc(worstImpact.n):'—'} — ${(worstImpact&&num(worstImpact.impact)?(worstImpact.impact*100).toFixed(1).replace('.',','):'—')} п.п.</div>
        </div>
      </div>
      <div class="panel"><div class="panel-title"><div><h3>Матрица «результат × динамика»</h3><p>Высокий/низкий результат и изменение места к IV кварталу 2025 года</p></div></div>
        <div class="management-grid">
          <div class="management-card"><h4>Высокий результат + рост</h4><p>${quadrant.hiUp} ТО. Лидеры, которые продолжают усиливаться.</p></div>
          <div class="management-card"><h4>Высокий результат + снижение</h4><p>${quadrant.hiDown} ТО. Формально сильные, но требуют внимания к устойчивости результата.</p></div>
          <div class="management-card"><h4>Низкий результат + рост</h4><p>${quadrant.loUp} ТО. Есть потенциал и положительная динамика.</p></div>
          <div class="management-card"><h4>Низкий результат + снижение</h4><p>${quadrant.loDown} ТО. Основная зона управленческого внимания.</p></div>
        </div>
      </div>
    </div>

    <div class="grid-2 equal">
      <div class="panel"><div class="panel-title"><div><h3>ТО vs ППК «Роскадастр»</h3><p>Каждая точка — территориальный орган; диагональ показывает равные значения</p></div></div><div id="analyticsScatter" class="chart"></div><div class="quadrant-note">Чем выше и правее точка, тем выше оба компонента. Точки заметно ниже диагонали указывают на более слабый результат ППК относительно ТО.</div></div>
      <div class="panel"><div class="panel-title"><div><h3>Федеральные округа</h3><p>Средние: ТО / ППК / комплексная оценка</p></div></div><div id="analyticsFo" class="chart"></div></div>
    </div>

    <div class="grid-2 equal">
      <div class="panel"><div class="panel-title"><div><h3>Направления — зоны внимания</h3><p>Среднее значение и количество ТО ниже 90%</p></div></div><div id="analyticsDirections" class="chart"></div></div>
      <div class="panel"><div class="panel-title"><div><h3>Динамика рейтинга</h3><p>Наибольший рост и снижение позиций</p></div></div><div id="analyticsMoves" class="chart small"></div></div>
    </div>

    <div class="grid-2 equal">
      <div class="panel"><div class="panel-title"><div><h3>Красная зона руководителя</h3><p>ТО с наибольшей совокупностью факторов риска</p></div></div>
        <div class="table-wrap"><table class="data-table analytics-table"><thead><tr><th>Регион</th><th>Оценка</th><th>Место</th><th>Динамика</th><th>Слабых напр.</th><th>Что тянет вниз</th></tr></thead><tbody>
        ${redZone.map(x=>`<tr class="clickable-row" data-region="${esc(x.n)}"><td><strong>${esc(x.n)}</strong><div class="subtle">${esc(x.fo)}</div></td><td>${pct(x.v)}</td><td>${rank(x.r)}</td><td>${deltaHtml(x.r,x.pr)}</td><td>${x.weakDirsCount}</td><td>${x.topDrag.map(d=>`${esc(SHORT[d.i])} (${((d.gap||0)*100).toFixed(1).replace('.',',')} п.п.)`).join('<br>')}</td></tr>`).join('')}
        </tbody></table></div>
      </div>
      <div class="panel"><div class="panel-title"><div><h3>Резерв роста</h3><p>Оценка эффекта, если подтянуть 3 самых слабых направления до среднего по РФ</p></div></div>
        <div class="table-wrap"><table class="data-table analytics-table"><thead><tr><th>Регион</th><th>Текущее место</th><th>Потенциал</th><th>Оценочное новое место</th><th>Рост, мест</th></tr></thead><tbody>
        ${reserves.map(x=>`<tr class="clickable-row" data-region="${esc(x.n)}"><td><strong>${esc(x.n)}</strong></td><td>${rank(x.r)}</td><td>${pct(x.v)} → ${pct(x.potentialScore)}</td><td>${rank(x.estimatedRank)}</td><td>${x.reserveRise?'<span class="delta-up">+'+x.reserveRise+'</span>':'—'}</td></tr>`).join('')}
        </tbody></table></div>
      </div>
    </div>

    <div class="grid-2 equal">
      <div class="panel"><div class="panel-title"><div><h3>Что тянет результат вниз</h3><p>Для 8 самых проблемных ТО — ключевые направления с наибольшим разрывом от среднего по РФ</p></div></div>
        <div class="kv-list">${attention.slice(0,8).map(x=>`<div class="kv-item"><div><strong>${esc(x.n)}</strong><span> · ${pct(x.v)} · место ${rank(x.r)}</span><div class="risk-tags">${x.topDrag.map(d=>`<span class="risk-tag">${esc(DIRECTIONS[d.i])}: -${((d.gap||0)*100).toFixed(1).replace('.',',')} п.п.</span>`).join('')}</div></div><div>${deltaHtml(x.r,x.pr)}</div></div>`).join('')}</div>
      </div>
      <div class="panel"><div class="panel-title"><div><h3>Тепловая карта «ТО × направления»</h3><p>Быстрый обзор распределения сильных и слабых мест по всем регионам</p></div></div>
        <div class="heatmap-wrap"><table class="heatmap-table"><thead><tr><th>Регион</th>${SHORT.map(s=>`<th>${esc(s)}</th>`).join('')}</tr></thead><tbody>
          ${heatRows.map(x=>`<tr class="clickable-row" data-region="${esc(x.n)}"><td><strong>${esc(x.n)}</strong><div class="subtle">${rank(x.r)} место</div></td>${DIRECTIONS.map((_,i)=>{ const v=x.d?.[i]?.[1]; const p=num(v)?Math.round(v*100):null; let bg='#eef2f7'; if(num(v)){ if(v>=0.97) bg='#cfeee2'; else if(v>=0.90) bg='#ffe7bf'; else bg='#ffd8d8'; } return `<td><div class="heatmap-cell" style="background:${bg}">${num(v)?p+'%':'—'}</div></td>`; }).join('')}</tr>`).join('')}
        </tbody></table></div>
      </div>
    </div>`;

  $$('#analyticsDashboard .clickable-row').forEach(tr=>tr.addEventListener('click',()=>{state.region=tr.dataset.region;setView('region');}));

  const scatter=usable.filter(x=>num(x.v)&&num(x.ppv)).map(x=>[+(x.v*100).toFixed(1),+(x.ppv*100).toFixed(1),x.n,x.fo,+(x.cv*100).toFixed(1)]);
  chart($('#analyticsScatter'),{tooltip:{trigger:'item',formatter:p=>`${esc(p.data[2])}<br>ТО: ${p.data[0]}%<br>ППК: ${p.data[1]}%<br>Комплексная: ${p.data[4]}%`},grid:{left:48,right:18,top:24,bottom:48,containLabel:true},xAxis:{name:'ТО, %',type:'value',min:Math.max(0,Math.floor(Math.min(...scatter.map(x=>x[0]),50)/5)*5),max:100},yAxis:{name:'ППК, %',type:'value',min:Math.max(0,Math.floor(Math.min(...scatter.map(x=>x[1]),35)/5)*5),max:100},series:[{type:'scatter',data:scatter,symbolSize:v=>8+Math.max(0,(v[4]-70)/4),itemStyle:{opacity:.72},markLine:{silent:true,symbol:'none',lineStyle:{type:'dashed'},data:[[{coord:[50,50]},{coord:[100,100]}]]}}]});

  chart($('#analyticsFo'),{tooltip:{trigger:'axis'},legend:{bottom:0},grid:{left:40,right:16,top:24,bottom:70,containLabel:true},xAxis:{type:'category',data:foStats.map(x=>x.fo)},yAxis:{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%'}},series:[{name:'ТО',type:'bar',data:foStats.map(x=>num(x.to)?+(x.to*100).toFixed(1):null),barMaxWidth:18},{name:'ППК',type:'bar',data:foStats.map(x=>num(x.ppk)?+(x.ppk*100).toFixed(1):null),barMaxWidth:18},{name:'Комплексная',type:'bar',data:foStats.map(x=>num(x.combined)?+(x.combined*100).toFixed(1):null),barMaxWidth:18}]});

  const weakDirTop=dirStats.slice(0,10);
  chart($('#analyticsDirections'),{tooltip:{trigger:'axis'},grid:{left:48,right:18,top:24,bottom:70,containLabel:true},xAxis:{type:'category',data:weakDirTop.map(x=>x.short),axisLabel:{rotate:25}},yAxis:[{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%'}},{type:'value',min:0}],legend:{bottom:0},series:[{name:'Среднее',type:'bar',data:weakDirTop.map(x=>+(x.avg*100).toFixed(1)),barMaxWidth:26},{name:'ТО ниже 90%',type:'line',yAxisIndex:1,data:weakDirTop.map(x=>x.below90),smooth:true}]});

  const gains=[...ranked].map(x=>({...x,d:delta(x.r,x.pr)})).filter(x=>x.d>0).sort((a,b)=>b.d-a.d).slice(0,6);
  const losses=[...ranked].map(x=>({...x,d:delta(x.r,x.pr)})).filter(x=>x.d<0).sort((a,b)=>a.d-b.d).slice(0,6);
  const moveLabels=[...gains.map(x=>'↑ '+x.n),...losses.map(x=>'↓ '+x.n)];
  const moveVals=[...gains.map(x=>x.d),...losses.map(x=>x.d)];
  chart($('#analyticsMoves'),{...chartBase(),grid:{left:56,right:18,top:24,bottom:24,containLabel:true},xAxis:{type:'value'},yAxis:{type:'category',data:moveLabels,axisLabel:{width:180,overflow:'truncate'}},series:[{type:'bar',data:moveVals,barMaxWidth:18,itemStyle:{borderRadius:[0,5,5,0]}}]});
}
