function normalizeName(v){return String(v??'').trim().toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ')} function toNum(v){return typeof v==='number'&&Number.isFinite(v)?v:null}
function parseIndicators(wb){const name=(wb.SheetNames||[]).find(n=>normalizeName(n).includes('показатели по направлениям'));if(!name)return{meta:[],data:{}};const a=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,raw:true,defval:null});const data={};for(const r of a){if(typeof r?.[0]==='number'&&r?.[1])data[r[1]]=state.indicatorMeta.map(m=>{const[c0,c1,c2,c3]=m.cols||[];return[r[c0]??null,c1==null?null:r[c1]??null,c2==null?null:r[c2]??null,c3==null?null:r[c3]??null]})}return{meta:state.indicatorMeta,data}}
function fromWorkbook(wb,fileName){const names=wb.SheetNames||[],ratingName=names.find(n=>normalizeName(n).includes('рейтинг то')&&normalizeName(n).includes('ппк'))||names.find(n=>normalizeName(n).includes('рейтинг то')),evalName=names.find(n=>normalizeName(n).includes('оценка и места по направлениям'))||names.find(n=>normalizeName(n).includes('места по направлениям'));if(!ratingName||!evalName)throw new Error('Не найдены листы рейтинга и оценки по направлениям');const a=XLSX.utils.sheet_to_json(wb.Sheets[ratingName],{header:1,raw:true,defval:null}),b=XLSX.utils.sheet_to_json(wb.Sheets[evalName],{header:1,raw:true,defval:null}),rm=new Map();a.forEach(r=>{if(typeof r?.[0]==='number'&&r?.[7])rm.set(normalizeName(r[7]),r)});const out=[];b.forEach(r=>{if(typeof r?.[0]!=='number'||!r?.[1])return;const q=rm.get(normalizeName(r[1]));if(!q)return;const d=[];for(let j=0;j<12;j++){const k=6+j*4;d.push([toNum(r[k]),toNum(r[k+1]),toNum(r[k+2]),toNum(r[k+3])])}out.push({n:r[1],fo:q[1],r:toNum(q[6]),pr:toNum(q[2]),sc:r[2],v:toNum(r[3]),s:toNum(r[4]),m:toNum(r[5]),ppr:toNum(q[90]),ppv:toNum(q[91]),cr:toNum(q[98]),cs:q[99],cv:toNum(q[100]),d})});if(!out.length)throw new Error('Не распознаны строки ТО');const title=String(a?.[0]?.[0]||b?.[0]?.[0]||''),m=title.match(/([IVX]+\s+квартал\s+20\d{2}\s+года?)/i),ind=parseIndicators(wb);return{data:out,meta:{period:m?m[1]:title.trim().slice(0,120)||'Период из файла',source:fileName},indicatorData:ind.data}}
$$('.nav-btn').forEach(b=>b.onclick=()=>setView(b.dataset.view));['metricFilter','foFilter','scaleFilter'].forEach(id=>$('#'+id).onchange=e=>{if(id==='metricFilter')state.metric=e.target.value;updateMeta();render()});$('#searchInput').oninput=render;$('#resetFilters').onclick=()=>{$('#metricFilter').value='to';state.metric='to';$('#foFilter').value='all';$('#scaleFilter').value='all';$('#searchInput').value='';render();updateMeta()};$('#fileInput').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;$('#parseStatus').textContent='Чтение…';try{const wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),p=fromWorkbook(wb,file.name);state.data=p.data;state.meta=p.meta;state.indicatorData=p.indicatorData||{};state.region=null;populateFilters();updateMeta();$('#fileName').textContent=file.name;$('#parseStatus').textContent='Готово';render()}catch(err){console.error(err);$('#parseStatus').textContent='Ошибка';alert('Не удалось обработать Excel: '+err.message)}};window.addEventListener('resize',()=>{state.charts.forEach(c=>c.resize());if(state.view==='map'&&state.mapMode==='fit')render()});populateFilters();updateMeta();render();
